const editions = text => /中英|中英文|中、英|中英双语/.test(text)?'Chinese and English Edition':/英法中/.test(text)?'English, French and Chinese Edition':/英法|英法双语/.test(text)?'English and French Edition':/英文|英语|全英版/.test(text)?'English Edition':/西语|西班牙/.test(text)?'Spanish Edition':/法语|法文/.test(text)?'French Edition':/日语|日文|日版/.test(text)?'Japanese Edition':/德语|德文/.test(text)?'German Edition':/俄语|俄文/.test(text)?'Russian Edition':/繁体中文|繁中/.test(text)?'Traditional Chinese Edition':/中文|简中/.test(text)?'Chinese Edition':null;
export function editionFor(c){if(/中英西意德荷六语/.test(c.sourceSku))return 'Multilingual Edition (Chinese, English, Spanish, Italian, German and Dutch)';return editions(c.sourceSku)||editions(c.records[0].descriptors.Language||'')||editions(c.sourceTitle);}
const names=['Prismatic Evolutions','Phantasmal Flames','Mega Evolution','Ascended Heroes','Perfect Order','Pitch Black','Chaos Rising','Scarlet Violet 151','Surging Sparks','Obsidian Flames','Paradox Rift','Temporal Forces','Crown Zenith','Paldean Fates','Scarlet Violet','Shrouded Fable','Twilight Masquerade','Shining Fates','Paldea Evolved','Battle Styles','Silver Tempest','Fusion Strike','Chilling Reign','Evolving Skies','Brilliant Stars','Lost Origin','Black Bolt','White Flare','Journey Together','Astral Radiance','Destined Rivals','Stellar Crown','Ultra Prism','Darkness Ablaze','Evolutions','Team Up','Hidden Fates','Lost Thunder','Unified Minds','Vivid Voltage','Sun Moon','Unbroken Bonds','Burning Shadows','Sword Shield'];
const compact=s=>s.toUpperCase().replace(/[^A-Z0-9]/g,'');
const aliases={FUDIONSTRIKE:'Fusion Strike',FUSIDNSTRIKE:'Fusion Strike',BAILLIANTSTARS:'Brilliant Stars',LOSTORICIN:'Lost Origin',LOSTDRIGIN:'Lost Origin',SIEJJARCROWN:'Stellar Crown',DESTINEDRIWALS:'Destined Rivals',PERFECTDRDER:'Perfect Order',TWOILIGHTMASQUERADE:'Twilight Masquerade',TWILIGHTMASOUERADE:'Twilight Masquerade',BRTTLESTYLES:'Battle Styles',BRTTLESIYEES:'Battle Styles',CHEICNGRELGN:'Chilling Reign',MEGAEWOLUTIONPHANTASMAL:'Phantasmal Flames'};
const short={EX:'Evolutions',GX:'Sun & Moon',TEAM:'Team Up',HID:'Hidden Fates',HIDD:'Hidden Fates',DARK:'Darkness Ablaze',ULT:'Ultra Prism',UNB:'Unbroken Bonds',SCA:'Scarlet & Violet',BUR:'Burning Shadows',MIN:'Unified Minds',EVO:'Evolving Skies',SWO:'Sword & Shield',BRI:'Brilliant Stars',SUR:'Surging Sparks',VIVI:'Vivid Voltage',LOST:'Lost Origin',PAL:'Paldea Evolved',THU:'Lost Thunder',JOU:'Journey Together',CHIL:'Chilling Reign',BATT:'Battle Styles',DEST:'Destined Rivals',AST:'Astral Radiance',WHITE:'White Flare',BLACK:'Black Bolt',CRO:'Crown Zenith',FATE:'Paldean Fates',SILV:'Silver Tempest',SHIN:'Shining Fates',FUS:'Fusion Strike',MEGA1:'Mega Evolution',MEGA2:'Phantasmal Flames',MEGA3:'Perfect Order',MEGA4:'Ascended Heroes',MEGA5:'Chaos Rising'};
const yNames=['Evolutions','Sun & Moon','Team Up','Hidden Fates','Darkness Ablaze','Ultra Prism','Scarlet & Violet 151','Unbroken Bonds','Scarlet & Violet','Burning Shadows','Unified Minds','Evolving Skies','Sword & Shield','Brilliant Stars','Surging Sparks','Vivid Voltage','Lost Origin','Paldea Evolved','Lost Thunder','Journey Together','Crown Zenith','Chilling Reign','Battle Styles','Destined Rivals','Shining Fates','Paldean Fates','Astral Radiance','White Flare','Black Bolt','Silver Tempest'];
function pokemonName(s){
 const text=compact(s);
 for(const [alias,name] of Object.entries(aliases))if(text.includes(alias))return name;
 const long=names.filter(n=>text.includes(compact(n))).sort((a,b)=>b.length-a.length);
 if(long.length)return long[0].replace('Scarlet Violet','Scarlet & Violet').replace('Sun Moon','Sun & Moon').replace('Sword Shield','Sword & Shield');
 if(/幻影之焰|幽幻烈焰/.test(s))return 'Phantasmal Flames';
 if(/PRISM/i.test(s)||/棱镜/.test(s))return 'Prismatic Evolutions';
 if(/PHANTASMAL|FLAMS|FLAMES/i.test(s))return 'Phantasmal Flames';
 if(/PERFECT/i.test(s))return 'Perfect Order';
 if(/CHAOS/i.test(s))return 'Chaos Rising';
 if(/ASCE/i.test(s))return 'Ascended Heroes';
 const y=s.match(/^Y(\d{2})/i);if(y && Number(y[1])<=30)return yNames[Number(y[1])-1];
 const model=s.match(/^(MEGA[1-5]|EX|GX|TEAM|HIDD?|DARK|ULT|UNB|SCA|BUR|MIN|EVO|SWO|BRI|SUR|VIVI|LOST|PAL|THU|JOU|CHIL|BATT|DEST|AST|WHITE|BLACK|CRO|FATE|SILV|SHIN|FUS)(?:[-\s\u3400-\u9fff]|$)/i);
 if(model)return short[model[1].toUpperCase()];
 if(/151/.test(s))return 'Scarlet & Violet 151';
 if(/白龙/.test(s))return 'White Flare';if(/黑龙/.test(s))return 'Black Bolt';
 if(/MEGA/i.test(s))return 'Mega Evolution';
 return {VOLTRGE:'Vivid Voltage',ULTRAPRISM:'Ultra Prism',DARKNESSABLAZE:'Darkness Ablaze',TEAMUP:'Team Up',HIDDENFATIS:'Hidden Fates',THUNDER:'Lost Thunder',ULRTA:'Ultra Prism',THLNDER:'Lost Thunder',HIDDEN:'Hidden Fates',UNIFIEDMINDS:'Unified Minds',VIVIDVOLTRGE:'Vivid Voltage',SUNMOON:'Sun & Moon'}[text]||null;
}
const replacements={ '四宫格':'4-Pocket','四格':'4-Pocket','九宫格':'9-Pocket','七龙珠':'Dragon Ball','鬼灭之刃':'Demon Slayer','鬼灭':'Demon Slayer','海贼王':'One Piece','火影':'Naruto','神奇宝贝':'Pokemon','宝可梦':'Pokemon','游戏王':'Yu-Gi-Oh!','卡册':'Card Binder','足球卡':'Football Cards','球星':'Sports Stars','烫金':'Gold-Foil Design','镭射':'Holographic','金色':'Gold','银色':'Silver','黑色':'Black','彩色':'Multicolor','炫彩':'Rainbow','彩虹':'Rainbow','金盒':'Gold','银盒':'Silver','黑盒':'Black','彩盒':'Multicolor','金':'Gold','银':'Silver','黑':'Black','彩':'Multicolor','白':'White','红':'Red','紫':'Purple','蓝':'Blue','版':'Version','款':'Model','卡位':'Card Slots'};
function simple(s){for(const [a,b]of Object.entries(replacements))s=s.split(a).join(' '+b+' ');return s.replace(/\s+/g,' ').replace(/^[\s-]+|[\s-]+$/g,'');}
function quantity(c){let m=c.sourceSku.match(/(\d+)\s*张/);if(!m)m=c.sourceSku.match(/(?<!\d)(324|360|72)(?!\d)/);if(!m)m=c.sourceTitle.match(/(\d+)\s*张/);return m?`${m[1]} Cards`:null;}
export function titleFor(c){
 let title=exact[c.index];
 const s=c.sourceSku,t=c.sourceTitle;
 let edition=editionFor(c);
 if(title){if(c.index<=12)edition='English Edition';return title+(edition&&!title.includes(edition)?' - '+edition:'');}
 if(/卡册|收纳册|收藏册|收集本/.test(t)){
  let theme=/七龙珠/.test(t)?'Dragon Ball':/海贼王/.test(t)?'One Piece':/游戏王/.test(t)?'Yu-Gi-Oh!':/足球|球星/.test(t)?'Sports':/火影/.test(t)?'Naruto':'Pokemon';
  if(/鬼灭/.test(s))theme='Demon Slayer';else if(/海贼/.test(s))theme='One Piece';else if(/火影/.test(s))theme='Naruto';else if(/七龙珠/.test(s))theme='Dragon Ball';
  const model=s.replace(/神奇宝贝四宫格卡册|七龙珠卡册|鬼灭卡册|海贼王卡册|火影卡册|游戏王卡册|神奇宝贝|烫金|镭射|卡册|火影|球星|七龙珠/g,'').replace(/^(火|金)-/,'').replace(/\/(4|9)格/,'').replace(/^[\s-]+|[\s-]+$/g,'');
  const capacity=/9格|九宫格/.test(s+' '+t)?'9-Pocket':/四宫格|四格|4格/.test(s+' '+t)?'4-Pocket':null;
  title=[theme,'Trading Card Binder',capacity,/镭射/.test(s)?'Holographic':/烫金|^金-/.test(s)?'Gold-Foil Design':null,'Design '+simple(model)].filter(Boolean).join(' - ');
  return /[\u3400-\u9fff]/.test(title)?null:title;
 }
 if(/宝可梦|神奇宝贝|pokemon|Pokémon|口袋妖怪/.test(t)){
  const name=pokemonName(s);
  if(name){title=`Pokemon ${name} Trading Cards`;const q=quantity(c);if(q)title+=' - '+q;
   if(/精英礼盒/.test(s))title+=' - Elite Trainer Box';
   return title+(edition?' - '+edition:'');}
  if(/金|银|黑|彩/.test(s)&&!/黑龙|白龙/.test(s)){
   const shade=/彩虹金|金彩虹/.test(s)?'Rainbow Gold':/彩虹银|银彩虹/.test(s)?'Rainbow Silver':/彩虹黑|黑彩虹/.test(s)?'Rainbow Black':/炫彩|彩色|彩/.test(s)?'Rainbow':/银/.test(s)?'Silver':/黑/.test(s)?'Black':'Gold';
   return ['Pokemon Foil Trading Cards',shade,quantity(c),edition].filter(Boolean).join(' - ');
  }
  if(/25周年|30周年/.test(s))return `Pokemon ${s.includes('25')?'25th':'30th'} Anniversary Trading Cards`+(edition?' - '+edition:'');
 }
 if(/足球|球星|世界杯/.test(t) && !/UNO/.test(t)){
  const design=s.replace(/\d+张(?:\/盒)?|\/盒|世界杯|足球卡?|英语|英文|2026|美加墨|新款|[（）【】]/g,'').trim();
  title=['Football Star Collectible Cards',/2026/.test(t+s)?'2026':null,simple(design),quantity(c),edition].filter(Boolean).join(' - ');
  return /[\u3400-\u9fff]/.test(title)?null:title;
 }
 return null;
}
